// 递归回溯，枚举选择指定数量的不同方案
void dfs(vector<int>& arr, int index, int level, vector<int>& path, vector<vector<int>>& res) {
    if (path.size() == level) {
        res.push_back(path);
        return;
    }
​
    for (int i = index; i < arr.size(); i++) {
        path.push_back(arr[i]);
        dfs(arr, i + 1, level, path, res);
        path.pop_back();
    }
}
