string getResult(vector<int>& arr, const string& num) {
    vector<int> link1, link2;
    // 处理器编号升序排序
    sort(arr.begin(), arr.end());
    // 按链路分类
    for (int e : arr) {
        if (e < 4) {
            link1.push_back(e);
        } else {
            link2.push_back(e);
        }
