    // 存储结果
    vector<vector<int>> ans;
    int len1 = link1.size();
    int len2 = link2.size();
    // 不同分配数量亲和性原则分配
    if (num == "1") {
        if (len1 == 1 || len2 == 1) {
            if (len1 == 1) {
                vector<int> path;
                dfs(link1, 0, 1, path, ans);
            }
            if (len2 == 1) {
                vector<int> path;
                dfs(link2, 0, 1, path, ans);
            }
        } else if (len1 == 3 || len2 == 3) {
