                dfs(link1, 0, 1, path, ans);
            }
            if (len2 == 2) {
                vector<int> path;
                dfs(link2, 0, 1, path, ans);
            }
        } else if (len1 == 4 || len2 == 4) {
            if (len1 == 4) {
                vector<int> path;
                dfs(link1, 0, 1, path, ans);
            }
            if (len2 == 4) {
                vector<int> path;
                dfs(link2, 0, 1, path, ans);
            }
        }
    } else if (num == "2") {
        if (len1 == 2 || len2 == 2) {
            if (len1 == 2) {
                vector<int> path;
                dfs(link1, 0, 2, path, ans);
            }
            if (len2 == 2) {
                vector<int> path;
                dfs(link2, 0, 2, path, ans);
            }
        } else if (len1 == 4 || len2 == 4) {
            if (len1 == 4) {
                vector<int> path;
                dfs(link1, 0, 2, path, ans);
            }
            if (len2 == 4) {
                vector<int> path;
                dfs(link2, 0, 2, path, ans);
            }
        } else if (len1 == 3 || len2 == 3) {
            if (len1 == 3) {
                vector<int> path;
                dfs(link1, 0, 2, path, ans);
            }
            if (len2 == 3) {
                vector<int> path;
                dfs(link2, 0, 2, path, ans);
            }
        }
    } else if (num == "4") {
        if (len1 == 4 || len2 == 4) {
            if (len1 == 4) ans.push_back(link1);
            if (len2 == 4) ans.push_back(link2);
        }
    } else if (num == "8") {
        if (len1 == 4 && len2 == 4) {
            vector<int> merged(link1.begin(), link1.end());
            merged.insert(merged.end(), link2.begin(), link2.end());
            ans.push_back(merged);
        }
    }
​
    // 格式化输出结果
    stringstream res;
    res << "[";
    for (size_t i = 0; i < ans.size(); ++i) {
        res << "[";
        for (size_t j = 0; j < ans[i].size(); ++j) {
            res << ans[i][j];
            if (j < ans[i].size() - 1) res << ", ";
        }
        res << "]";
        if (i < ans.size() - 1) res << ", ";
    }
    res << "]";
    return res.str();
}
