import (
    "bufio"
    "fmt"
    "os"
    "strings"
    "strconv"
)
// 递归回溯，枚举选择指定数量的不同方案
func dfs(arr []int, index, level int, path []int, res *[][]int) {
    if len(path) == level {
        *res = append(*res, append([]int(nil), path...))
        return
    }
    for i := index; i < len(arr); i++ {
        path = append(path, arr[i])
        dfs(arr, i+1, level, path, res)
        path = path[:len(path)-1]
    }
}
