func getResult(arr []int, num string) string {
    var link1, link2 []int
    // 按照编号升序
    sort.Ints(arr)
    // 按照链路分类存储
    for _, e := range arr {
        if e < 4 {
            link1 = append(link1, e)
        } else {
            link2 = append(link2, e)
        }
    }
​
