    len1 := len(link1)
    len2 := len(link2)
    // 不同分配数量亲和性原则分配
    switch num {
    case "1":
        if len1 == 1 || len2 == 1 {
            if len1 == 1 {
                var path []int
                dfs(link1, 0, 1, path, &ans)
            }
            if len2 == 1 {
                var path []int
                dfs(link2, 0, 1, path, &ans)
            }
        } else if len1 == 3 || len2 == 3 {
            if len1 == 3 {
                var path []int
                dfs(link1, 0, 1, path, &ans)
            }
            if len2 == 3 {
                var path []int
                dfs(link2, 0, 1, path, &ans)
            }
        } else if len1 == 2 || len2 == 2 {
            if len1 == 2 {
                var path []int
                dfs(link1, 0, 1, path, &ans)
            }
            if len2 == 2 {
                var path []int
                dfs(link2, 0, 1, path, &ans)
            }
        } else if len1 == 4 || len2 == 4 {
            if len1 == 4 {
                var path []int
                dfs(link1, 0, 1, path, &ans)
            }
            if len2 == 4 {
                var path []int
                dfs(link2, 0, 1, path, &ans)
            }
        }
    case "2":
        if len1 == 2 || len2 == 2 {
            if len1 == 2 {
                var path []int
                dfs(link1, 0, 2, path, &ans)
            }
            if len2 == 2 {
                var path []int
                dfs(link2, 0, 2, path, &ans)
            }
        } else if len1 == 4 || len2 == 4 {
            if len1 == 4 {
                var path []int
                dfs(link1, 0, 2, path, &ans)
            }
            if len2 == 4 {
                var path []int
                dfs(link2, 0, 2, path, &ans)
            }
        } else if len1 == 3 || len2 == 3 {
            if len1 == 3 {
                var path []int
                dfs(link1, 0, 2, path, &ans)
            }
            if len2 == 3 {
                var path []int
                dfs(link2, 0, 2, path, &ans)
            }
        }
    case "4":
        if len1 == 4 || len2 == 4 {
            if len1 == 4 {
                ans = append(ans, link1)
            }
            if len2 == 4 {
                ans = append(ans, link2)
            }
        }
    case "8":
        if len1 == 4 && len2 == 4 {
            merged := append(link1, link2...)
            ans = append(ans, merged)
        }
    }
    // 格式化输出
    var sb strings.Builder
    sb.WriteString("[")
    for i, sub := range ans {
        sb.WriteString("[")
        for j, v := range sub {
            sb.WriteString(strconv.Itoa(v))
            if j < len(sub)-1 {
                sb.WriteString(", ")
            }
        }
        sb.WriteString("]")
        if i < len(ans)-1 {
            sb.WriteString(", ")
        }
    }
    sb.WriteString("]")
​
    return sb.String()
}
